#!/usr/bin/env python3
"""Writes src/layout/fontink.js: for the capitals A-G of Barlow Condensed (400 / 500 / 600 / 700), the rightmost point of the ink at each height
(rows every 0.02 em from the baseline up to 0.80 em), read from the glyph outlines of the @fontsource woff files. Used to place the quality and the bass of a chord
symbol against the real shape of the root letter. Usage: python3 tools/extract-font-ink.py <folder with barlow-condensed-latin-<w>-normal.woff>"""
import sys, json
from fontTools.ttLib import TTFont
from fontTools.pens.basePen import BasePen

STEP, ROWS = 0.02, 41

class Flatten(BasePen):
    def __init__(self, gs):
        super().__init__(gs); self.contours = []; self.cur = []
    def _moveTo(self, p): self.cur = [p]
    def _lineTo(self, p): self.cur.append(p)
    def _curveToOne(self, a, b, c):
        p0 = self.cur[-1]
        for i in range(1, 17):
            t = i / 16; m = 1 - t
            self.cur.append((m**3*p0[0] + 3*m*m*t*a[0] + 3*m*t*t*b[0] + t**3*c[0], m**3*p0[1] + 3*m*m*t*a[1] + 3*m*t*t*b[1] + t**3*c[1]))
    def _qCurveToOne(self, a, b):
        p0 = self.cur[-1]
        for i in range(1, 17):
            t = i / 16; m = 1 - t
            self.cur.append((m*m*p0[0] + 2*m*t*a[0] + t*t*b[0], m*m*p0[1] + 2*m*t*a[1] + t*t*b[1]))
    def _closePath(self): self.contours.append(self.cur); self.cur = []
    def _endPath(self): self.contours.append(self.cur); self.cur = []

def profile(font, ch):
    gs = font.getGlyphSet(); name = font.getBestCmap()[ord(ch)]
    pen = Flatten(gs); gs[name].draw(pen); u = font['head'].unitsPerEm
    rows = []
    for k in range(ROWS):
        y = k * STEP * u; best = None
        for poly in pen.contours:
            n = len(poly)
            for i in range(n):
                (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % n]
                if (y1 <= y < y2) or (y2 <= y < y1) or (y1 == y2 == y and True):
                    if y1 == y2: xs = [x1, x2]
                    else: xs = [x1 + (y - y1) * (x2 - x1) / (y2 - y1)]
                    for x in xs: best = x if best is None else max(best, x)
        rows.append(None if best is None else round(best / u, 3))
    return rows

src = sys.argv[1]
out = {}
for w in (400, 500, 600, 700):
    f = TTFont(f'{src}/barlow-condensed-latin-{w}-normal.woff')
    out[w] = {ch: profile(f, ch) for ch in 'ABCDEFG'}
with open('src/layout/fontink.js', 'w') as o:
    o.write("// Generated by tools/extract-font-ink.py (Barlow Condensed, SIL OFL): rightmost ink of each capital A-G, in em from the glyph origin, at heights 0, 0.02 … 0.80 em above the baseline (null = no ink).\n")
    o.write(f"export const INK_STEP = {STEP};\nexport const BARLOW_INK = " + json.dumps(out) + ";\n")
